SELECT
s.*,
si.name AS stationName
FROM station_config s
LEFT JOIN station_info si ON s.station_id = si.id AND si.deleted = 0
WHERE s.deleted = 0


    AND s.id = #{pageReqVO.id}


    AND s.station_id = #{pageReqVO.stationId}


    AND s.type = #{pageReqVO.type}


    AND s.content = #{pageReqVO.content}


    AND s.status = #{pageReqVO.status}


    AND s.audit_time BETWEEN #{pageReqVO.auditTime[0]} AND #{pageReqVO.auditTime[1]}


    AND s.audit_user_id = #{pageReqVO.auditUserId}


    AND s.sync_time BETWEEN #{pageReqVO.syncTime[0]} AND #{pageReqVO.syncTime[1]}


    AND s.remark = #{pageReqVO.remark}


    AND s.reserve1 = #{pageReqVO.reserve1}


    AND s.reserve2 = #{pageReqVO.reserve2}


    AND s.creator = #{pageReqVO.creator}


    AND s.updater = #{pageReqVO.updater}


    AND s.create_time BETWEEN #{pageReqVO.createTime[0]} AND #{pageReqVO.createTime[1]}


    AND s.update_time BETWEEN #{pageReqVO.updateTime[0]} AND #{pageReqVO.updateTime[1]}


ORDER BY s.id DESC
